entries[1307245] = { ["name"] = "Fish Bowl", ["text"] = "1 yd range10 sec cast 1 hour cooldown\nPlaces a small fish bowl that allows you and others sitting nearby to gain 8% increased stats, mutually exclusive with Blessing of Kings.\n\nRequires a Campfire nearby. All camping features share a cooldown of 1 hour." }
