entries[1307247] = { ["name"] = "Fishing Rack", ["text"] = "1 yd range10 sec cast 1 hour cooldown\nPlaces a Fishing Rack that grants the ability to catch uncommon fish for 1 hour, provides Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby.\n\nMay be placed over a Fish Bowl to replace it. All camping features share a cooldown of 1 hour." }
entries[1307248] = { ["name"] = "Greenhouse", ["text"] = "1 yd range10 sec cast 1 hour cooldown\nPlaces a Greenhouse that will grow herbs over time from seeds planted, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\nMay be placed over an Incense Candle to replace it.\nAll camping features share a cooldown of 1 hour." }
entries[1307251] = { ["name"] = "Incense Candle", ["text"] = "1 yd range10 sec cast 1 hour cooldown\nIgnites an incense candle that allows you and others sitting nearby to gain [2][6][12][18][25] increased Intellect, mutually exclusive with Arcane Intellect.\n\nRequires a Campfire nearby. All camping features share a cooldown of 1 hour." }
entries[1307252] = { ["name"] = "Journeyman Campfire", ["text"] = "2 - 3 yd range\n10 sec cast 5 min cooldown\nBuilds a journeyman campfire that allows cooking and the placement of up to 5 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features." }
entries[1307254] = { ["name"] = "Lodestone", ["text"] = "1 yd range10 sec cast 1 hour cooldown\nErects a lodestone that allows you and others sitting nearby to gain [12][20][32][49][67][90] increased melee Attack Power, mutually exclusive with Blessing of Might.\n\nRequires a Campfire nearby. All camping features share a cooldown of 1 hour." }
entries[1307255] = { ["name"] = "Loom", ["text"] = "1 yd range10 sec cast 1 hour cooldown\nPlaces a Loom usable for recipes that require it, and provides all the benefits of a Faction Banner. Requires a Campfire nearby.\n\nMay be placed over a Faction Banner to replace it. All camping features share a cooldown of 1 hour." }
entries[1307257] = { ["name"] = "Cookie's Feast", ["text"] = "1 yd range10 sec cast 1 hour cooldown\nLay out Cookie's Feast that contains Stamina-boosting food. Requires a Cooking Fire nearby. All camping features share a cooldown of 1 hour." }
